import { Button } from "@/src/shared/ui/components/button";
import { MoreIcon } from "@/src/shared/ui/components/icon/svg/more.icon";
import { Menu } from "@/src/shared/ui/components/menu";
import { twMerge } from "tailwind-merge";
import { useTicketItemOptions } from "../state/use-ticket-item-options";

type Props = {
	className?: string;
	ticketId: string;
	deleteTicket: () => void;
};

export function TicketItemMenu(props: Props) {
	const { className, ticketId, deleteTicket } = props;

	const options = useTicketItemOptions({ deleteTicket, ticketId });

	if (options.length === 0) return null;

	return (
		<Menu>
			<Button
				shape="square"
				variant="ghost"
				className={twMerge("shrink-0", className)}
				size="small"
				data-testid="ticket-item-menu"
			>
				<MoreIcon size={16} />
			</Button>
			<Menu.Content placement="bottom end">
				{options.map((option) => (
					<Menu.Item
						onAction={option.action}
						key={option.title}
						isDisabled={option.disabled}
					>
						{option.icon}
						{option.title}
					</Menu.Item>
				))}
			</Menu.Content>
		</Menu>
	);
}
